export type AgariEventsPluginPdas = {
  config: typeof findConfigPda;
  result: typeof findResultPda;
  ledger: typeof findLedgerPda;
  mvault: typeof findMvaultPda;
};

export type AgariEventsPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function agariEventsProgram() {
  return <T extends AgariEventsPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { agariEvents: AgariEventsPlugin }> => {
    return extendClient(client, {
      agariEvents: <AgariEventsPlugin>{
        accounts: {
          book: addSelfFetchFunctions(client, getBookCodec()),
          globalConfig: addSelfFetchFunctions(client, getGlobalConfigCodec()),
          ledger: addSelfFetchFunctions(client, getLedgerCodec()),
          market: addSelfFetchFunctions(client, getMarketCodec()),
          marketResult: addSelfFetchFunctions(client, getMarketResultCodec()),
          series: addSelfFetchFunctions(client, getSeriesCodec()),
        },
        instructions: {
          adminAddBook: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAdminAddBookInstructionAsync(input),
            ),
          adminAddPolicyVersion: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAdminAddPolicyVersionInstructionAsync(input),
            ),
          adminInitConfig: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAdminInitConfigInstructionAsync(input),
            ),
          adminRegisterSeries: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAdminRegisterSeriesInstructionAsync(input),
            ),
          adminSetAuthorities: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAdminSetAuthoritiesInstructionAsync(input),
            ),
          adminSetMode: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAdminSetModeInstructionAsync(input),
            ),
          productAddDependent: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getProductAddDependentInstructionAsync(input),
            ),
          productReleaseDependent: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getProductReleaseDependentInstructionAsync(input),
            ),
          publicCloseLedger: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPublicCloseLedgerInstructionAsync(input),
            ),
          publicCloseMarket: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPublicCloseMarketInstructionAsync(input),
            ),
          publicCopyOpenFromPrev: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPublicCopyOpenFromPrevInstruction(input),
            ),
          publicGrowLedger: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPublicGrowLedgerInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          publicRecordPrintAttested: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPublicRecordPrintAttestedInstructionAsync(input),
            ),
          publicRecordPrintPyth: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPublicRecordPrintPythInstruction(input),
            ),
          publicRecordPrintRedstone: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPublicRecordPrintRedstoneInstructionAsync(input),
            ),
          publicRedeemFor: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPublicRedeemForInstructionAsync(input),
            ),
          publicReleaseBook: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPublicReleaseBookInstruction(input),
            ),
          publicSettleWindow: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPublicSettleWindowInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          publicSweepExpired: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPublicSweepExpiredInstruction(input),
            ),
          publicVoidExpired: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPublicVoidExpiredInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          rollerOpenWindow: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRollerOpenWindowInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          userCancelAll: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUserCancelAllInstructionAsync(input),
            ),
          userCancelOrders: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUserCancelOrdersInstructionAsync(input),
            ),
          userMergeCompleteSet: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUserMergeCompleteSetInstructionAsync(input),
            ),
          userMintCompleteSet: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUserMintCompleteSetInstructionAsync(input),
            ),
          userPlaceOrder: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUserPlaceOrderInstructionAsync(input),
            ),
          userRedeem: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUserRedeemInstructionAsync(input),
            ),
          userReduceOrder: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUserReduceOrderInstruction(input),
            ),
          userWithdrawCredit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUserWithdrawCreditInstructionAsync(input),
            ),
        },
        pdas: {
          config: findConfigPda,
          result: findResultPda,
          ledger: findLedgerPda,
          mvault: findMvaultPda,
        },
        identifyAccount: identifyAgariEventsAccount,
        identifyInstruction: identifyAgariEventsInstruction,
        parseInstruction: parseAgariEventsInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
